    private PagedGrid? conditions;
    private bool Allowed(HomestayAction action)=>detail?.AllowedActions.Contains(action)==true;
    private void SetEnabled(){foreach(var pair in actions){var action=pair.Key==suspendButton&&detail?.Homestay.Status==HomestayStatus.Suspended?HomestayAction.Reopen:pair.Value;pair.Key.Enabled=Allowed(action);if(pair.Key==editFuturePrice)pair.Key.Enabled=Allowed(action)&&CanEditFuturePrice();}suspendButton.Text=detail?.Homestay.Status==HomestayStatus.Suspended?"Mở lại":"Tạm ngưng";}
    private bool CanEditFuturePrice(){if(detail is null||grid5.Grid.SelectedRows.Count!=1)return false;var i=(grid5.Query.PageNumber-1)*grid5.Query.PageSize+grid5.Grid.SelectedRows[0].Index;return i>=0&&i<detail.Prices.Versions.Count&&!detail.Prices.Versions[i].HasTakenEffect;}private void AddActions(TabPage tab,params (string Text,HomestayAction? Action,Func<Task> Apply)[] items){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};foreach(var item in items){var b=new Button{Text=item.Text,AutoSize=true};if(item.Action is {} a)actions[b]=a;b.Click+=async(_,_)=>await Write(b,item.Apply);bar.Controls.Add(b);}tab.Controls.Add(bar);bar.BringToFront();}
    private Task Write(Button button,Func<Task> apply)=>RunMutationAsync(button,async()=>{if(detail is null)throw new BusinessException("Vui lòng tải lại hồ sơ.");await apply();await ReloadAsync();},ReloadAsync,()=>!actions.TryGetValue(button,out var action)||Allowed(button==suspendButton&&detail?.Homestay.Status==HomestayStatus.Suspended?HomestayAction.Reopen:action));
    private static T Selected<T>(PagedGrid grid,IReadOnlyList<T> items)=>items[(grid.Query.PageNumber-1)*grid.Query.PageSize+EmployeeUi.Selected(grid)];
    public Task RefreshFromServerAsync()=>ReloadAsync();
    private async Task ReloadAsync(){detail=null;SetEnabled();await loader.LoadAsync(async ct=>{
        var d=await services!.Homestays.GetAsync(homestayId,ct);var list=services.Can(Permission.RoomCalendarView)?await services.Rooms.ListBlocksAsync(new(homestayId,d.Approval.Today.AddDays(-31),d.Approval.Today.AddDays(365)),ct):Array.Empty<RoomBlockItem>();return(d,list);
    },result=>{
        detail=result.d;blocks=result.list;if(!detail.CanViewLegalDocuments)viewTabs.TabPages.Remove(tab3);else if(!viewTabs.TabPages.Contains(tab3))viewTabs.TabPages.Insert(Math.Min(3,viewTabs.TabCount),tab3);if(!detail.CanViewContracts)viewTabs.TabPages.Remove(tab7);else if(!viewTabs.TabPages.Contains(tab7))viewTabs.TabPages.Insert(Math.Min(7,viewTabs.TabCount),tab7);approvalNotice.Text=detail.Homestay.CreatedByUserId==services!.Session!.UserId&&detail.Homestay.Status==HomestayStatus.PendingReview?"Cần Quản lý khác duyệt hồ sơ do bạn tạo":"";var h=detail.Homestay;heading.Text="F16 · "+h.Name;filterPanelField0.Text=h.Name;filterPanelField1.Text=LiveUi.Status(h.Status);filterPanelField2.SetItems([new(){Id=h.OwnerId,Name=h.OwnerName}]);filterPanelField2.SelectId(h.OwnerId);
        EmployeeUi.Local(grid0,new (string,string?)[]{("Tên",h.Name),("Địa chỉ",h.Address),("Liên hệ",h.ContactPhone),("Giờ nhận / trả",h.CheckinTime.ToString("HH:mm")+" / "+h.CheckoutTime.ToString("HH:mm")),("Mô tả",h.Description),("Hướng dẫn",h.CheckinGuide),("Lý do trạng thái",h.StatusReason)},r=>[r.Item1,r.Item2]);
        EmployeeUi.Local(grid1,detail.Amenities,r=>[r.Name]);EmployeeUi.Local(grid2,detail.Images,r=>[r.File.FileName,r.IsCover?"Có":"",r.RoomTypeId is int id?TypeName(id):"Toàn homestay",r.SortOrder]);
        EmployeeUi.Local(grid3,detail.Documents,r=>[LiveUi.Status(r.DocumentType),r.File.FileName,r.ExpiryDate?.ToString("dd/MM/yyyy"),r.IsSuperseded?"Đã thay thế":"Hiện dùng"]);
        EmployeeUi.Local(grid4,detail.RoomTypes,r=>[r.Name,r.CategoryName,r.MaxGuests,r.AreaM2,r.IsActive?"Đang bán":"Ngừng bán"]);EmployeeUi.Local(roomGrid,detail.Rooms,r=>[r.RoomCode,TypeName(r.RoomTypeId),r.IsActive?"Đang bán":"Ngừng bán",r.Note]);
        EmployeeUi.Local(grid5,detail.Prices.Versions,r=>[TypeName(r.RoomTypeId),EmployeeUi.Date(r.EffectiveFrom),r.WeekdayPrice is decimal w?EmployeeUi.Money(w):"Thiếu",r.WeekendPrice is decimal e?EmployeeUi.Money(e):"Thiếu",r.HolidayPrice is decimal p?EmployeeUi.Money(p):"Thiếu",r.HasTakenEffect?"Có":"Chưa"]);
        EmployeeUi.Local(grid6,detail.CancellationPolicies,r=>[r.Name,LiveUi.Status(r.Scope),r.IsActive?"Đang dùng":"Đã tắt",string.Join("; ",r.Rules.Select(x=>x.MinDaysBefore+" ngày: "+x.RefundPercent+"%"))]);
        EmployeeUi.Local(grid7,detail.Contracts,r=>[r.ContractNo,EmployeeUi.Date(r.StartDate),EmployeeUi.Date(r.EndDate),r.CommissionRate.ToString("P2"),LiveUi.Status(r.Status)]);EmployeeUi.Local(grid8,detail.Audit,r=>[EmployeeUi.Time(r.CreatedAtUtc),r.ActorName,r.ActionCode,r.Note]);
        EmployeeUi.Local(blockGrid,blocks,r=>[detail.Rooms.FirstOrDefault(x=>x.Id==r.RoomId)?.RoomCode,EmployeeUi.Date(r.StartDate),EmployeeUi.Date(r.EndDate),LiveUi.Status(r.Reason),r.Note]);
        EmployeeUi.Local(conditions!,detail.Approval.Conditions,r=>[r.Message,r.IsSatisfied?"Đạt":"Còn thiếu"]);SetEnabled();
    });}
    private string TypeName(int id)=>detail!.RoomTypes.FirstOrDefault(r=>r.Id==id)?.Name??"Loại phòng đã ngừng dùng";
    private Lookup[] Types()=>detail!.RoomTypes.Select(r=>new Lookup{Id=r.Id,Name=r.Name}).ToArray();
    private async Task EditHome(){var h=detail!.Homestay;using var d=ListingDraftEditors.Homestay(await services!.Owners.LookupAsync(),await services.Homestays.ListAreasAsync());foreach(var pair in new (string,object?)[]{("owner",h.OwnerId),("area",h.AreaId),("name",h.Name),("address",h.Address),("phone",h.ContactPhone),("description",h.Description),("guide",h.CheckinGuide),("checkin",h.CheckinTime),("checkout",h.CheckoutTime)})LiveUi.Fill(d,pair.Item1,pair.Item2);if(d.ShowDialog(this)==DialogResult.OK){var updated=await services.Homestays.UpdateAsync(new(homestayId,FrmHomestays.Values(d),h.RowVer));if(h.Status==HomestayStatus.Active&&updated.Homestay.Status==HomestayStatus.PendingReview)MessageBox.Show(this,"Thay đổi địa chỉ hoặc khu vực đã đưa hồ sơ về Chờ duyệt lại.","Hồ sơ cần duyệt lại");}}
    private async Task Transition(HomestayAction action){var note=LiveUi.Note(this,LiveUi.Status(action),action is HomestayAction.Return or HomestayAction.Suspend or HomestayAction.Reopen or HomestayAction.End);if(note is null)return;var r=new HomestayStatusRequest(homestayId,detail!.Homestay.RowVer,string.IsNullOrWhiteSpace(note)?null:note);await(action switch{HomestayAction.Submit=>services!.Homestays.SubmitAsync(r),HomestayAction.Approve=>services!.Homestays.ApproveAsync(r),HomestayAction.Return=>services!.Homestays.ReturnAsync(r),HomestayAction.Suspend=>services!.Homestays.SuspendAsync(r),HomestayAction.Reopen=>services!.Homestays.ReopenAsync(r),_=>services!.Homestays.EndAsync(r)});}
    private async Task SetAmenities(){var all=await services!.Homestays.ListAmenitiesAsync();using var d=new FieldsDialog("Tiện nghi",all.Select(a=>new FieldSpec("a"+a.Id,a.Name,FieldKind.Confirmation,detail!.Amenities.Any(x=>x.Id==a.Id),Required:false)).ToArray());if(d.ShowDialog(this)==DialogResult.OK)await services.Homestays.SetAmenitiesAsync(new(homestayId,all.Where(a=>d.Values["a"+a.Id] is true).Select(a=>a.Id).ToArray(),detail!.Homestay.RowVer));}
    private async Task Upload(bool document){using var picker=new OpenFileDialog{Filter=EvidencePresentation.FileFilter};if(picker.ShowDialog(this)!=DialogResult.OK)return;var file=await EvidencePresentation.ReadAsync(picker.FileName);
        if(document){using var d=new FieldsDialog("Giấy tờ pháp lý",new("type","Loại giấy tờ",FieldKind.Choice,DocumentType.BusinessLicense,Choices:Enum.GetValues<DocumentType>().Select(x=>new Choice(x,LiveUi.Status(x))).ToArray()),new("expiry","Ngày hết hạn",FieldKind.Date,Required:false));if(d.ShowDialog(this)==DialogResult.OK)await services!.Homestays.AddDocumentAsync(new(homestayId,(DocumentType)d.Values["type"]!,file.Content,file.FileName,d.Values["expiry"] as DateOnly?,detail!.Homestay.RowVer));}
        else{using var d=new FieldsDialog("Ảnh homestay",new("type","Loại phòng (trống: toàn homestay)",FieldKind.Lookup,Required:false,Choices:Types().Select(t=>new Choice(t.Id,t.Name)).ToArray()),new("caption","Chú thích",Required:false,MaxLength:200),new("order","Thứ tự",FieldKind.Integer,0,Minimum:0),new("cover","Đặt làm ảnh bìa",FieldKind.Confirmation,false,Required:false));if(d.ShowDialog(this)==DialogResult.OK)await services!.Homestays.AddImageAsync(new(homestayId,file.Content,file.FileName,d.Values["type"] as int?,LiveUi.Optional(d,"caption"),LiveUi.Id(d,"order"),d.Values["cover"] is true,detail!.Homestay.RowVer));}}
    private async Task OpenFile(bool document){var meta=document?Selected(grid3,detail!.Documents).File:Selected(grid2,detail!.Images).File;var file=document?await services!.Files.GetHomestayDocumentAsync(homestayId,meta.FileId):await services!.Files.GetHomestayImageAsync(homestayId,meta.FileId);EvidencePresentation.Show(this,file,meta.FileName);}
    private async Task EditImage(){var r=Selected(grid2,detail!.Images);using var d=new FieldsDialog("Thông tin ảnh",new("type","Loại phòng (trống: toàn homestay)",FieldKind.Lookup,r.RoomTypeId,Required:false,Choices:Types().Select(t=>new Choice(t.Id,t.Name)).ToArray()),new("caption","Chú thích",Initial:r.Caption,Required:false,MaxLength:200),new("order","Thứ tự",FieldKind.Integer,r.SortOrder,Minimum:0),new("cover","Ảnh bìa",FieldKind.Confirmation,r.IsCover,Required:false));if(d.ShowDialog(this)==DialogResult.OK)await services!.Homestays.UpdateImageAsync(new(homestayId,r.Id,d.Values["type"] as int?,LiveUi.Optional(d,"caption"),LiveUi.Id(d,"order"),d.Values["cover"] is true,detail.Homestay.RowVer));}private async Task SetCover(){var r=Selected(grid2,detail!.Images);await services!.Homestays.UpdateImageAsync(new(homestayId,r.Id,r.RoomTypeId,r.Caption,r.SortOrder,true,detail.Homestay.RowVer));}
    private async Task RemoveImage(){var r=Selected(grid2,detail!.Images);if(MessageBox.Show(this,"Gỡ ảnh "+r.File.FileName+"?","Gỡ ảnh",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await services!.Homestays.RemoveImageAsync(new(homestayId,r.Id,detail.Homestay.RowVer));}
    private async Task RemoveDocument(){var r=Selected(grid3,detail!.Documents);var reason=LiveUi.Note(this,"Gỡ giấy tờ "+r.File.FileName);if(reason is not null){var wasActive=detail.Homestay.Status==HomestayStatus.Active;var updated=await services!.Homestays.RemoveDocumentAsync(new(homestayId,r.Id,reason,detail.Homestay.RowVer));if(wasActive&&updated.Homestay.Status==HomestayStatus.PendingReview)MessageBox.Show(this,"Gỡ giấy tờ pháp lý đã đưa hồ sơ về Chờ duyệt lại.","Hồ sơ cần duyệt lại");}}
    private async Task EditType(bool edit){var r=edit?Selected(grid4,detail!.RoomTypes):null;using var d=ListingDraftEditors.RoomType(await services!.Homestays.ListRoomCategoriesAsync());if(r is not null){LiveUi.Fill(d,"category",r.CategoryId);LiveUi.Fill(d,"name",r.Name);LiveUi.Fill(d,"guests",r.MaxGuests);LiveUi.Fill(d,"area",r.AreaM2);LiveUi.Fill(d,"description",r.Description);}if(d.ShowDialog(this)!=DialogResult.OK)return;if(r is null)await services.Rooms.CreateTypeAsync(new(homestayId,LiveUi.Id(d,"category"),LiveUi.Text(d,"name"),LiveUi.Id(d,"guests"),d.Values["area"] as int?,LiveUi.Optional(d,"description"),detail!.Homestay.RowVer));else await services.Rooms.UpdateTypeAsync(new(r.Id,LiveUi.Id(d,"category"),LiveUi.Text(d,"name"),LiveUi.Id(d,"guests"),d.Values["area"] as int?,LiveUi.Optional(d,"description"),detail!.Homestay.RowVer));}
    private async Task ToggleType(){var r=Selected(grid4,detail!.RoomTypes);await services!.Rooms.SetTypeActiveAsync(new(r.Id,!r.IsActive,detail.Homestay.RowVer));}
    private async Task EditRoom(bool edit){var r=edit?Selected(roomGrid,detail!.Rooms):null;using var d=ListingDraftEditors.Room(Types());if(r is not null){LiveUi.Fill(d,"type",r.RoomTypeId);d.Controls.Find("type",true).Single().Enabled=false;LiveUi.Fill(d,"code",r.RoomCode);LiveUi.Fill(d,"note",r.Note);}if(d.ShowDialog(this)!=DialogResult.OK)return;if(r is null)await services!.Rooms.CreateRoomAsync(new(LiveUi.Id(d,"type"),LiveUi.Text(d,"code"),LiveUi.Optional(d,"note"),detail!.Homestay.RowVer));else await services!.Rooms.UpdateRoomAsync(new(r.Id,LiveUi.Text(d,"code"),LiveUi.Optional(d,"note"),detail!.Homestay.RowVer));}
    private async Task ToggleRoom(){var r=Selected(roomGrid,detail!.Rooms);await services!.Rooms.SetRoomActiveAsync(new(r.Id,!r.IsActive,detail.Homestay.RowVer));}
    private async Task EditPrice(bool edit){var r=edit?Selected(grid5,detail!.Prices.Versions):null;if(r?.HasTakenEffect==true)throw new BusinessException("Giá đã hiệu lực không được sửa. Hãy thêm phiên bản mới.");using var d=ListingDraftEditors.Price(Types(),detail!.Prices.Today);if(r is not null){LiveUi.Fill(d,"type",r.RoomTypeId);LiveUi.Fill(d,"effective",r.EffectiveFrom);LiveUi.Fill(d,"weekday",r.WeekdayPrice);LiveUi.Fill(d,"weekend",r.WeekendPrice);LiveUi.Fill(d,"holiday",r.HolidayPrice);d.Controls.Find("type",true).Single().Enabled=d.Controls.Find("effective",true).Single().Enabled=false;}if(d.ShowDialog(this)!=DialogResult.OK)return;var type=LiveUi.Id(d,"type");var date=(DateOnly)d.Values["effective"]!;var a=(decimal)d.Values["weekday"]!;var b=(decimal)d.Values["weekend"]!;var c=(decimal)d.Values["holiday"]!;if(edit)await services!.Rooms.UpdatePriceAsync(new(type,date,a,b,c,detail.Homestay.RowVer));else await services!.Rooms.AddPriceAsync(new(type,date,a,b,c,detail.Homestay.RowVer));}
    private async Task Block(){using var d=ListingDraftEditors.Block(detail!.Rooms.Select(r=>new Lookup{Id=r.Id,Name=r.RoomCode}).ToArray(),detail.Approval.Today);if(d.ShowDialog(this)==DialogResult.OK)await services!.Rooms.BlockAsync(new(LiveUi.Id(d,"room"),(DateOnly)d.Values["start"]!,(DateOnly)d.Values["end"]!,Enum.Parse<RoomBlockReason>(LiveUi.Text(d,"reason")),LiveUi.Optional(d,"note"),detail.Homestay.RowVer));}
    private async Task Unblock(){var r=Selected(blockGrid,blocks);var reason=LiveUi.Note(this,"Mở khóa phòng");if(reason is not null)await services!.Rooms.UnblockAsync(new(r.Id,reason,detail!.Homestay.RowVer));}
    private static CancellationRuleItem[] ParseRules(string text)=>text.Split('\n',StringSplitOptions.RemoveEmptyEntries).Select(line=>{var parts=line.Split('=');if(parts.Length!=2||!int.TryParse(parts[0].Trim(),out var day)||!int.TryParse(parts[1].Trim(),out var pct))throw new BusinessException("Mỗi dòng cần dạng số ngày = phần trăm, ví dụ 7 = 100.");return new CancellationRuleItem(day,pct);}).ToArray();
    private async Task AddPolicy(){using var d=new FieldsDialog("Chính sách hủy riêng",new("name","Tên chính sách",MaxLength:100),new("scope","Phạm vi",FieldKind.Choice,CancellationScope.All,Choices:Enum.GetValues<CancellationScope>().Select(x=>new Choice(x,LiveUi.Status(x))).ToArray()),new("rules","Mốc hoàn: mỗi dòng số ngày = phần trăm",FieldKind.Multiline,"7 = 100\n0 = 0"));d.ValidateValues=v=>{try{ParseRules((string)v["rules"]!);return null;}catch(BusinessException e){return e.Message;}};if(d.ShowDialog(this)==DialogResult.OK)await services!.Homestays.SetCancellationPolicyAsync(new(homestayId,new(){Name=LiveUi.Text(d,"name"),Scope=(CancellationScope)d.Values["scope"]!,Rules=ParseRules(LiveUi.Text(d,"rules"))},detail!.Homestay.RowVer));}
    private async Task DisablePolicy(){var r=Selected(grid6,detail!.CancellationPolicies);await services!.Homestays.DisableCancellationPolicyAsync(new(homestayId,r.Id,detail.Homestay.RowVer));}
    protected override bool ProcessCmdKey(ref Message m,Keys k){if(services is not null&&k==Keys.F5){reload.PerformClick();return true;}return base.ProcessCmdKey(ref m,k);}
}